<template><AppShell title="确认下单" back footer><StateView :loading="loading" :error="error" :count="item?1:0" @retry="load" /><view v-if="item&&!error&&!loading" class="pad"><view class="checkout-steps"><text class="bold">① 确认道具</text><text>② 支付</text><text>③ 游戏内交付</text></view><view class="card row"><GameArt variant="mini" class="mini-cover" :game="item.game" /><view class="stack flex-1"><text class="bold">{{item.title}}</text><text class="muted">{{item.nickname}} · {{item.shopStatus==='APPROVED'?'认证店铺':'未认证店铺'}}</text></view></view><view class="card"><view class="field-row"><text>游戏区服</text><text>{{gameServerLabel(item)}}</text></view><view class="field-row"><text>道具分类</text><text>{{item.itemCategory}}</text></view><view v-if="item.pricingMode==='UNIT'" class="field-row purchase-quantity"><text>购买数量</text><view class="quantity-control"><button class="ui-button" :disabled="busy||!!purchasePayload||Number(quantity)<=1" @click="quantity=String(Math.max(1,Number(quantity)-1))">−</button><input v-model="quantity" :disabled="busy||!!purchasePayload" @blur="quantity=$event.detail.value" type="number" aria-label="购买数量" /><button class="ui-button" :disabled="busy||!!purchasePayload||Number(quantity)>=maxQuantity" @click="quantity=String(Number(quantity)+1)">＋</button></view></view><text v-if="item.pricingMode==='UNIT'" class="muted tiny">可购买 {{maxQuantity}} 件 · 每件 ¥{{money(item.priceCents)}}</text><view v-else class="field-row"><text>整批数量</text><text>{{item.quantity}} 件</text></view><text class="field-label section">道具介绍</text><text class="summary-text" style="display:block">{{item.itemDetails}}</text><image v-for="src in images(item.detailImages)" :key="src" class="snapshot-detail-image" :src="imageUrl(src)" mode="widthFix" @click="previewMedia(images(item.detailImages),src)" /><template v-if="item.pricingMode!=='UNIT'&&item.deliveryTerms"><text class="field-label section">交付约定</text><text class="summary-text" style="display:block">{{item.deliveryTerms}}</text></template></view><view class="card"><label class="field-label">交易备注（选填）</label><textarea v-model="note" @blur="note=$event.detail.value" class="textarea" placeholder="游戏内交付时间、补充要求等" maxlength="1000" /></view><view class="card"><text class="field-label">费用明细</text><view class="field-row"><text>{{item.pricingMode==='UNIT'?'单价 × 数量':'整批总价'}}</text><text>{{item.pricingMode==='UNIT'?'¥'+money(item.priceCents)+' × '+quantity+' = ':''}}¥{{money(subtotal)}}</text></view><view class="field-row"><text>优惠券</text><picker :range="couponOptions" range-key="label" @change="couponIndex=Number($event.detail.value)"><view class="picker-value"><text :class="{danger:discount>0}">{{couponOptions[couponIndex]?.label}}</text><AppIcon class="app-icon" name="chevron" :size="14" /></view></picker></view><button v-if="couponMore" class="ui-button text-button" :disabled="couponBusy" @click="moreCoupons">加载更多优惠券</button><view class="field-row"><text class="bold">实付款</text><text class="price">¥{{money(total)}}</text></view></view><view class="notice"><AppIcon class="app-icon" name="shield" :size="18" /><text>{{session.config?.paymentsEnabled===false?'支付暂未开放，当前仅创建待付款订单，可取消':session.config?.simulatedPayment?'本地测试支付，不扣除真实资金':'微信支付，付款后等待卖家交付道具'}}</text></view><view class="check-row" @click="agreed=!agreed"><text :class="['check-box',{checked:agreed}]">{{agreed?'✓':''}}</text><text>我已确认道具介绍、区服及购买数量，并同意</text><text class="link" @click.stop="go('account/index',{type:'rules'})">交易规则</text></view></view><text v-if="submitError" class="field-error" style="display:block;padding:12px 16px">{{submitError}}</text><template #footer><view class="stack"><text class="tiny muted">合计</text><text class="price">¥{{money(total)}}</text></view><button class="ui-button btn" :disabled="busy||(!purchasePayload&&(!item||!validQuantity))" @click="submit">{{busy?'正在创建订单…':purchasePayload?'恢复已有订单':session.config?.paymentsEnabled===false?'确认下单':'确认下单并支付'}}</button></template></AppShell></template>
<script setup>
import {gameServerLabel} from '../../lib/playerTrade';import {computed,ref,watch} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import {request,session,requireLogin,money,go,payOrder,loadConfig,loadMe,toast,images,imageUrl} from '../../lib/api';import {previewMedia} from '../../lib/media';import {retryIntent,pendingIntent,completeIntent} from '../../lib/retryIntent'
const id=ref(''),item=ref(null),loading=ref(false),error=ref(''),submitError=ref(''),busy=ref(false),note=ref(''),agreed=ref(false),couponIndex=ref(0),coupons=ref([]),couponPage=ref(1),couponMore=ref(false),couponBusy=ref(false);let loadVersion=0,purchaseIntent=null,orderId=null,recoveryRequired=false;const quantity=ref('1'),purchasePayload=ref(null);const maxQuantity=computed(()=>item.value?.availableQuantity??item.value?.quantity??0),validQuantity=computed(()=>item.value?.pricingMode!=='UNIT'||(/^\d+$/.test(quantity.value)&&Number(quantity.value)>=1&&Number(quantity.value)<=maxQuantity.value)),subtotal=computed(()=>item.value?(item.value.priceCents*(item.value.pricingMode==='UNIT'&&validQuantity.value?Number(quantity.value):item.value.pricingMode==='UNIT'?0:1)):0);watch(quantity,()=>{agreed.value=false;couponIndex.value=0})
watch(()=>session.token,()=>{loadVersion++;loading.value=false;note.value='';quantity.value='1';coupons.value=[];couponIndex.value=0;purchasePayload.value=null;purchaseIntent=null;orderId=null;recoveryRequired=false;agreed.value=false;item.value=null;error.value='';submitError.value='登录身份已变化，请重新核对商品；原订单可在我的订单中查看';busy.value=false})
const couponOptions=computed(()=>[{label:'不使用优惠券',discountCents:0},...coupons.value.filter(c=>!c.usedOrderId&&new Date(c.expiresAt)>new Date()&&c.minimumCents<=subtotal.value).map(c=>({...c,label:c.title+' -¥'+money(c.discountCents)}))]);const discount=computed(()=>couponOptions.value[couponIndex.value]?.discountCents||0);const total=computed(()=>item.value?Math.max(1,subtotal.value-discount.value):0)
onLoad(q=>id.value=q.id);onShow(()=>{if(requireLogin())load()})
async function load(){
 if(loading.value)return
 const currentLoad=++loadVersion,actorToken=session.token,previousQuote=item.value?.quoteKey,selectedCoupon=couponOptions.value[couponIndex.value]?.id
 loading.value=true;error.value=''
 try{
  await loadMe();if(actorToken!==session.token||currentLoad!==loadVersion)return
  const stored=pendingIntent('checkout_'+id.value)
  if(stored){purchaseIntent=stored;purchasePayload.value={...stored.payload,requestKey:stored.requestKey};recoveryRequired=true;loading.value=false;await submit();return}
  if(purchasePayload.value){recoveryRequired=true;loading.value=false;await submit();return}
  item.value=null
  const r=await Promise.all([request('/boost/listings/'+id.value),request('/boost/coupons'),loadConfig()]);if(actorToken!==session.token||currentLoad!==loadVersion)return
  if(r[0].kind!=='SERVICE'||r[0].businessType!=='PLAYER_ITEM')throw new Error('请从卖家的道具商品下单')
  item.value=r[0];coupons.value=r[1].items;couponMore.value=r[1].hasMore;couponPage.value=1;couponIndex.value=Math.max(0,couponOptions.value.findIndex(c=>c.id===selectedCoupon));if((previousQuote&&previousQuote!==item.value.quoteKey)||(selectedCoupon&&couponIndex.value===0))agreed.value=false
 }catch(e){if(actorToken===session.token&&currentLoad===loadVersion){item.value=null;error.value=e.message}}finally{if(actorToken===session.token&&currentLoad===loadVersion)loading.value=false}
}
async function moreCoupons(){if(couponBusy.value)return;couponBusy.value=true;try{const d=await request('/boost/coupons','GET',{page:couponPage.value+1});coupons.value=[...coupons.value,...d.items];couponPage.value++;couponMore.value=d.hasMore}catch(e){toast(e.message)}finally{couponBusy.value=false}}
async function submit(){
 if(busy.value||loading.value)return
 if(!purchasePayload.value&&(error.value||!item.value))return
 if(!purchasePayload.value&&(!validQuantity.value||subtotal.value>10000000)){submitError.value='请选择库存范围内的整数件数，单笔总价不超过 100000 元';return}
 if(!purchasePayload.value&&!agreed.value){submitError.value='请先确认道具介绍、区服及购买数量并同意交易规则';return}
 const actorToken=session.token
 busy.value=true;submitError.value=''
 try{if(!orderId){if(!purchasePayload.value){purchaseIntent=retryIntent('checkout_'+id.value,{listingId:Number(id.value),quoteKey:item.value.quoteKey,expectedAmountCents:total.value,note:note.value,couponId:couponOptions.value[couponIndex.value]?.id,...(item.value.pricingMode==='UNIT'?{quantity:Number(quantity.value)}:{})});purchasePayload.value={...purchaseIntent.payload,requestKey:purchaseIntent.requestKey}};const o=await request('/boost/orders','POST',purchasePayload.value);if(actorToken!==session.token)return;orderId=o.id;if(purchaseIntent)completeIntent(purchaseIntent)}if(recoveryRequired){toast(session.config?.paymentsEnabled===false?'已恢复待付款订单，请核对订单内容':'已恢复订单，请核对金额和道具信息后付款');uni.redirectTo({url:'/pages/orders/detail?id='+orderId});return}if(session.config?.paymentsEnabled!==false)await payOrder(orderId);uni.redirectTo({url:'/pages/orders/detail?id='+orderId})}
 catch(e){if(actorToken!==session.token)return;if(!orderId&&e.code&&e.code<500){if(purchaseIntent)completeIntent(purchaseIntent);purchaseIntent=null;purchasePayload.value=null}if(!orderId&&(!e.code||e.code>=500))recoveryRequired=true;if(e.code===409&&!orderId){agreed.value=false;couponIndex.value=0;busy.value=false;await load()}submitError.value=e.message;if(orderId)uni.redirectTo({url:'/pages/orders/detail?id='+orderId})}
 finally{if(actorToken===session.token)busy.value=false}
}
</script>
<style scoped>.snapshot-detail-image{display:block;width:100%;margin-top:12px;border-radius:8px}.quantity-control{display:flex;align-items:center;gap:4px}.quantity-control .ui-button{width:44px;height:44px;text-align:center;background:#f6f6f8;border-radius:8px}.quantity-control input{width:52px;max-width:52px!important;text-align:center}.purchase-quantity{margin-bottom:6px}.checkout-steps{display:flex;justify-content:space-between;color:#aaa;font-size:11px;padding:2px 4px 18px}.checkout-steps .bold{color:#191919}.fixed-footer .btn{margin-left:20px}.checkout-steps{padding:2px 5px 14px}.checkout-steps .bold{background:#fff8c8;border-radius:20px;padding:2px 8px}.card .textarea{min-height:82px}.card .field-row{min-height:43px}.card>.field-label{margin-bottom:4px}</style>
